import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
snacks = list(map(int, data[1:]))

tower = []
largest_snack_seen = 0

for snack in snacks:
    if snack == largest_snack_seen + 1:
        tower.append(snack)
        largest_snack_seen = snack
    else:
        if snack > largest_snack_seen:
            largest_snack_seen = snack
        else:
            tower.insert(0, snack)

    if tower[-1] == n:
        print(" ".join(map(str, tower)))
        tower = []

